const fs=require('fs'),path=require('path'),{execFileSync}=require('child_process');
const dir=process.cwd(),file=path.join(dir,'config.json'),IND=2;
const phases=[
 '0 前置查证：pwd / 目录内容 / config.json 是否存在 / JSON 解析器',
 '1 创建 v1：写入 {"name":"demo","retries":3}（2 空格缩进，固定风格）',
 '2 校验 v1：用解析器读回，确认仅有 name、retries 两键',
 '3 升级 v2：保留原序，末尾追加 "enabled":true、"version":2（改前留备份）',
 '4 校验与取证：解析最终文件，打印完整内容与键顺序'
];
const done=new Set();
const showTodo=()=>{console.log('--- TODO ---');phases.forEach((p,i)=>console.log((done.has(i)?'[x] ':'[ ] ')+p));console.log('------------');};
function runValidator(){
  return execFileSync(process.execPath,['-e',
"const fs=require('fs');const o=JSON.parse(fs.readFileSync(process.argv[1],'utf8'));console.log('parsed OK | keys='+JSON.stringify(Object.keys(o))+' | values='+JSON.stringify(o));",
file],{encoding:'utf8'}).trim();
}
function check(tag){
  console.log('['+tag+'] 校验命令: node -e "JSON.parse(require(\'fs\').readFileSync(\'config.json\',\'utf8\'))"');
  const out=runValidator();
  console.log('['+tag+'] 解析输出: '+out);
  return JSON.parse(fs.readFileSync(file,'utf8'));
}
console.log('GOAL: 把 config.json 从 v1 {"name":"demo","retries":3} 升级为 v2（末尾追加 "enabled":true、"version":2），已有键值与顺序不变，并打印最终内容作为证据');
showTodo();

console.log('=== 阶段 0 前置查证 ===');
console.log('pwd =',dir);
console.log('工作目录内容 =',JSON.stringify(fs.readdirSync(dir)));
console.log('JSON 解析器 = node '+process.version+'（命令见各阶段“校验命令”行）');
const exists=fs.existsSync(file);
console.log('config.json 是否已存在 =',exists);
done.add(0);showTodo();

console.log('=== 阶段 1 创建 v1 ===');
const v1obj={name:'demo',retries:3};
let v1text;
if(exists){
  const cur=fs.readFileSync(file,'utf8');
  console.log('已存在的 config.json 原文 >>>');console.log(cur);console.log('<<<');
  let same=false;try{same=JSON.stringify(JSON.parse(cur))===JSON.stringify(v1obj);}catch(e){same=false;}
  if(!same){
    console.log('STOP: config.json 已存在且不等价于 v1，按预案不覆盖、不合并，请指示如何处理。');
    showTodo();process.exit(0);
  }
  console.log('已存在内容等价于 v1（仅比键值），视为阶段 1 已完成，不重写文件。');
  v1text=cur;
}else{
  v1text=JSON.stringify(v1obj,null,IND);
  fs.writeFileSync(file,v1text);
  console.log('写入内容 >>>');console.log(v1text);console.log('<<<');
}
done.add(1);check('阶段1校验');showTodo();

console.log('=== 阶段 2 校验 v1 ===');
const o1=check('阶段2校验');
const k1=Object.keys(o1);
console.log('键列表 =',JSON.stringify(k1));
if(!(k1.length===2&&k1[0]==='name'&&k1[1]==='retries'&&o1.name==='demo'&&o1.retries===3)){
  console.log('STOP: v1 校验失败（键或值不符）。');showTodo();process.exit(0);
}
console.log('v1 校验通过：仅 name、retries 两键，值 demo / 3。');
done.add(2);showTodo();

console.log('=== 阶段 3 升级 v2 ===');
const backup=fs.readFileSync(file,'utf8');
console.log('备份(v1 原文, 内存) >>>');console.log(backup);console.log('<<<');
const v2obj={name:o1.name,retries:o1.retries,enabled:true,version:2};
const v2text=JSON.stringify(v2obj,null,IND);
fs.writeFileSync(file,v2text);
console.log('写入内容 >>>');console.log(v2text);console.log('<<<');
done.add(3);

console.log('=== 阶段 4 校验与取证 ===');
let parsed;
try{parsed=check('阶段4校验');}
catch(e){console.log('解析失败: '+e.message);fs.writeFileSync(file,backup);console.log('已回退到 v1 原文，未留下解析失败版本。');showTodo();process.exit(1);}
const keys=Object.keys(parsed),expect=['name','retries','enabled','version'];
const ok=JSON.stringify(keys)===JSON.stringify(expect)&&parsed.name==='demo'&&parsed.retries===3&&parsed.enabled===true&&parsed.version===2&&typeof parsed.version==='number'&&typeof parsed.enabled==='boolean';
if(!ok){
  console.log('校验不通过：keys='+JSON.stringify(keys)+' 或值/类型不符 → 回退到 v1 原文。');
  fs.writeFileSync(file,backup);showTodo();process.exit(1);
}
console.log('--- 最终文件完整内容 ---');
console.log(fs.readFileSync(file,'utf8'));
console.log('--- 结束 ---');
console.log('最终键顺序列表 =',JSON.stringify(keys));
done.add(4);showTodo();
console.log('DONE: config.json 已升级为 v2，键顺序 '+JSON.stringify(keys)+'，JSON 解析校验通过，完整内容见上方打印。');
